{"implementation":"import math


def solve(case):
    if not isinstance(case, dict):
        raise ValueError('case must be an object')
    payload = case.get('payload') if set(case) == {'payload'} else case
    if not isinstance(payload, dict):
        raise ValueError('payload must be an object')
    if 'nodes' not in payload or 'required_symbols' not in payload:
        raise ValueError('missing required payload field')
    nodes = payload['nodes']
    required_symbols = payload['required_symbols']
    if not isinstance(nodes, list) or not nodes:
        raise ValueError('nodes must be a nonempty list')
    if not isinstance(required_symbols, list) or any(not isinstance(s, str) for s in required_symbols):
        raise ValueError('required_symbols must be a list of strings')
    if len(set(required_symbols)) != len(required_symbols):
        raise ValueError('required_symbols must be unique')

    by_id = {}
    children = {}
    for node in nodes:
        if not isinstance(node, dict):
            raise ValueError('each node must be an object')
        needed = {'id', 'parent', 'symbol', 'depth', 'removable', 'utility'}
        if not needed.issubset(node):
            raise ValueError('node is missing a required field')
        node_id = node['id']
        parent = node['parent']
        symbol = node['symbol']
        depth = node['depth']
        utility = node['utility']
        if not isinstance(node_id, str) or not node_id:
            raise ValueError('node id must be a nonempty string')
        if node_id in by_id:
            raise ValueError('node ids must be unique')
        if parent is not None and (not isinstance(parent, str) or not parent):
            raise ValueError('parent must be null or a nonempty string')
        if not isinstance(symbol, str) or not symbol:
            raise ValueError('symbol must be a nonempty string')
        if isinstance(depth, bool) or not isinstance(depth, int) or depth < 0:
            raise ValueError('depth must be a nonnegative integer')
        if not isinstance(node['removable'], bool):
            raise ValueError('removable must be a boolean')
        if isinstance(utility, bool) or not isinstance(utility, (int, float)) or not math.isfinite(utility):
            raise ValueError('utility must be a finite number')
        by_id[node_id] = node
        children[node_id] = []

    roots = []
    for node_id, node in by_id.items():
        parent = node['parent']
        if parent is None:
            roots.append(node_id)
        else:
            if parent not in by_id or parent == node_id:
                raise ValueError('node parent is invalid')
            if by_id[parent]['depth'] + 1 != node['depth']:
                raise ValueError('parent and child depths are inconsistent')
            children[parent].append(node_id)
    if len(roots) != 1 or by_id[roots[0]]['depth'] != 0:
        raise ValueError('nodes must form a single rooted tree')

    visited = set()
    stack = [roots[0]]
    while stack:
        node_id = stack.pop()
        if node_id in visited:
            raise ValueError('nodes must form a tree')
        visited.add(node_id)
        stack.extend(children[node_id])
    if len(visited) != len(by_id):
        raise ValueError('nodes must form a connected tree')

    present_symbols = {}
    for node in by_id.values():
        present_symbols[node['symbol']] = present_symbols.get(node['symbol'], 0) + 1
    if any(symbol not in present_symbols for symbol in required_symbols):
        raise ValueError('a required symbol is not represented')

    candidate_order = sorted(
        (node_id for node_id, node in by_id.items() if node['removable']),
        key=lambda node_id: (-by_id[node_id]['depth'], node_id),
    )
    retained = set(by_id)
    removal_order = []
    required = set(required_symbols)
    for node_id in candidate_order:
        node = by_id[node_id]
        if node_id == roots[0] or node['symbol'] in required:
            continue
        if any(child_id in retained for child_id in children[node_id]):
            continue
        if node['symbol'] in required and present_symbols[node['symbol']] <= 1:
            continue
        retained.remove(node_id)
        present_symbols[node['symbol']] -= 1
        removal_order.append(node_id)

    return {
        'retained_ids': sorted(retained),
        'removal_order': removal_order,
        'grammar_valid': True,
        'interestingness_preserved': all(present_symbols.get(symbol, 0) > 0 for symbol in required_symbols),
        'registered_candidate_order': candidate_order,
        'stable_ties': True,
    }
"}
